  // Misc pages
  { path: 'user/AccountPage.vue', title: 'Tài khoản', desc: 'Trang quản lý tài khoản người dùng' },
  { path: 'app/RatingPage.vue', title: 'Đánh giá ứng dụng', desc: 'Trang đánh giá ứng dụng' },
  { path: 'app/FeedbackPage.vue', title: 'Phản hồi', desc: 'Trang gửi phản hồi' },
  { path: 'app/SharePage.vue', title: 'Chia sẻ ứng dụng', desc: 'Trang chia sẻ ứng dụng' },
];

// Tạo thư mục và file
const basePath = 'src/pages';

pages.forEach(page => {
  const fullPath = path.join(basePath, page.path);
  const dir = path.dirname(fullPath);

  // Tạo thư mục nếu chưa có
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  // Tạo file nếu chưa có
  if (!fs.existsSync(fullPath)) {
    const content = createPageTemplate(page.title, page.desc);
    fs.writeFileSync(fullPath, content);
    console.log(`Created: ${fullPath}`);
  } else {
    console.log(`Exists: ${fullPath}`);
  }
});

console.log('\\nAll pages created successfully!');
